import { useState } from "react";
import ComUsage from "./ComUsage";
import GenStats from "./GenStats";

function App() {
  const [page, setPage] = useState("usage");
  const [darkMode, setDarkMode] = useState(true);

  const theme = darkMode
    ? {
        bg: "#121212",
        text: "#ffffff",
        header: "#1e1e1e",
        card: "#1f1f1f",
        button: "#333",
      }
    : {
        bg: "#f5f5f5",
        text: "#000000",
        header: "#e0e0e0",
        card: "#ffffff",
        button: "#555",
      };

  return (
    <div style={{ background: theme.bg, color: theme.text, minHeight: "100vh" }}>
      <header style={{ background: theme.header, padding: "15px", textAlign: "center" }}>
        <h1 style={{ margin: 0 }}>Pokémon Analytics Dashboard</h1>

        <nav style={{ marginTop: "10px" }}>
          <button onClick={() => setPage("usage")} style={navButtonStyle(page === "usage", theme)}>Usage</button>
          <button onClick={() => setPage("stats")} style={navButtonStyle(page === "stats", theme)}>Stats</button>
          <button onClick={() => setDarkMode(!darkMode)} style={navButtonStyle(false, theme)}>
            {darkMode ? "Light Mode" : "Dark Mode"}
          </button>
        </nav>
      </header>

      <main style={{ padding: "20px" }}>
        {page === "usage" && <ComUsage theme={theme} />}
        {page === "stats" && <GenStats theme={theme} />}
      </main>
    </div>
  );
}

const navButtonStyle = (active, theme) => ({
  margin: "0 10px",
  padding: "8px 15px",
  background: active ? "#4CAF50" : theme.button,
  color: "white",
  border: "none",
  cursor: "pointer",
  borderRadius: "5px"
});

export default App;
